<script setup>
import { Head, router } from '@inertiajs/vue3';
import MemberLayout from '@/Layouts/MemberLayout.vue';
defineProps({ profileComplete: Boolean, applications: Object, statusLabels: Object });
const submit = () => { if (confirm('Ajukan permohonan keanggotaan?')) router.post(route('member.applications.store')); };
</script>
<template>
    <Head title="Permohonan Keanggotaan" />
    <MemberLayout><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold text-aski-700">KEANGGOTAAN</p><h1 class="mt-1 text-3xl font-bold text-aski-900">Permohonan Keanggotaan</h1></div><button v-if="profileComplete" class="btn-primary" @click="submit">Ajukan Permohonan</button></div><div v-if="!profileComplete" class="mt-6 rounded-xl border border-gold-400 bg-gold-100 p-4 text-sm text-gold-600">Lengkapi profil Anda terlebih dahulu sebelum mengajukan permohonan.</div><div class="mt-7 space-y-4"><article v-for="application in applications.data" :key="application.id" class="card p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-bold text-aski-900">Permohonan #{{ application.id }}</p><p class="mt-1 text-sm text-slate-500">Diajukan {{ new Date(application.submitted_at).toLocaleDateString('id-ID') }}</p></div><span class="rounded-full bg-aski-100 px-3 py-1 text-xs font-semibold text-aski-800">{{ statusLabels[application.status] }}</span></div><div v-if="application.admin_note" class="mt-4 rounded-lg bg-slate-50 p-3 text-sm"><span class="font-semibold">Catatan Admin:</span> {{ application.admin_note }}</div><div class="mt-5 border-t border-slate-100 pt-4"><p class="mb-2 text-sm font-semibold text-slate-700">Riwayat</p><ol class="space-y-2 text-sm"><li v-for="history in application.histories" :key="history.id" class="flex gap-3"><span class="mt-1 h-2 w-2 rounded-full bg-gold-400"></span><span><b>{{ statusLabels[history.status] }}</b> · {{ new Date(history.created_at).toLocaleString('id-ID') }}<span v-if="history.note"> — {{ history.note }}</span></span></li></ol></div></article><div v-if="applications.data.length === 0" class="card p-8 text-center text-slate-500">Belum ada riwayat permohonan.</div></div></MemberLayout>
